from qgis.PyQt.QtWidgets import QAction, QDockWidget

mw = iface.mainWindow()
dock = mw.findChild(QDockWidget, 'AdvancedDigitizingTools')
acts = {a.objectName(): a for a in dock.findChildren(QAction)}
out = {}

# CAD再有効化
if not acts['mEnableAction'].isChecked():
    acts['mEnableAction'].trigger()
out['cad_on'] = acts['mEnableAction'].isChecked()

# 作図モード実行
cm = acts['mConstructionModeAction']
out['cm_before'] = {'enabled': cm.isEnabled(), 'checked': cm.isChecked()}
if cm.isEnabled():
    cm.trigger()
    out['cm_after'] = {'checked': cm.isChecked()}
else:
    out['cm_after'] = 'still disabled'
result = out
"}
